#nullable enable // autogenerated

using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.tanookiZombie_State)]
    public class TanookiZombie_StateBehaviour : EnemyStateBehaviour
    {
        public TanookiZombie_StateBehaviour(string nsp, string name) : base(nsp, name)
        {
        }
        protected override int GetActiveState(Entity enemy)
        {
            if (enemy.IsPerformingSpecialMove())
            {
                return STATE_JUMP;
            }
            return base.GetActiveState(enemy);
        }
        public const int STATE_JUMP = VanillaEnemyStates.TANOOKI_ZOMBIE_JUMP;
    }
}
